{
  "name": "@jimmyyen/graphify-opencode-plugin",
  "version": "0.5.0",
  "description": "OpenCode plugin for Graphify: slash commands for project initialization and graph infrastructure",
  "license": "MIT",
  "author": "jimmyyen",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/cawa0505/opencode-graphify-plugin.git"
  },
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "keywords": ["opencode", "opencode-plugin", "graphify", "ast", "graph"],
  "files": ["dist", "README.md", "LICENSE"],
  "scripts": {
    "build": "tsc",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "npm run build"
  },
  "dependencies": {
    "@opencode-ai/plugin": "1.17.18"
  },
  "devDependencies": {
    "@types/node": "^26.1.1",
    "typescript": "^5.0.0"
  }
}
